func:
// === Fleet Manifest Loader with Validation ===
// Expects msg.payload to be JSON string from File In node

try {
    const raw = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload;
    if (!raw || typeof raw !== "object") throw new Error("Manifest is not an object");
    if (!raw.devices || typeof raw.devices !== "object") throw new Error("Manifest missing devices");

    // Normalize device keys to uppercase 12-hex (strip separators)
    const normDevices = {};
    for (const [k, v] of Object.entries(raw.devices)) {
        const nk = String(k).toUpperCase().replace(/[^0-9A-F]/g, "");
        if (!/^[0-9A-F]{12}$/.test(nk)) {
            node.warn(`Skipping invalid MAC key: ${k}`);
            continue;
        }
        normDevices[nk] = v;
    }

    const manifest = { ...raw, devices: normDevices };

    global.set("fleet_manifest", manifest);
    flow.set("manifest", manifest);

    const count = Object.keys(manifest.devices).length;
    node.log(`Loaded manifest fleet_id=${manifest.fleet_id}, devices=${count}`);
    msg.payload = manifest;
    return msg;
} catch (e) {
    node.error(`Failed to load manifest: ${e.message}`, msg);
    return null;
}

// === Bootstrap Config Router ===
// Expected incoming topic format: bootstrap/announce/{deviceID}

// --- Parse topic ---
const parts = (msg.topic || '').split('/');
if (parts.length < 3) return null;       // Ignore if topic is too short

// Extract deviceID and normalize to uppercase
const deviceID = (parts[2] || '').toUpperCase();

// --- Load manifest from global ---
const manifest = global.get('fleet_manifest');
if (!manifest || !manifest.devices) {
    node.warn("Manifest not loaded in global context");
    return null;
}

// Build a normalized lookup table (all keys uppercase)
const norm = {};
for (const [k, v] of Object.entries(manifest.devices)) {
    norm[k.toUpperCase()] = v;
}

// Find the device entry
const entry = norm[deviceID];
if (!entry) {
    node.warn(`Unknown device: ${deviceID}`);
    return null;
}

// --- Check status from payload ---
const st = msg.payload?.status;
if (st === 'bootstrapped') {
    // Already bootstrapped, nothing more to do
    return null;
}

// --- Build response message ---
return {
    topic: `bootstrap/config/${deviceID}`,
    payload: {
        fleet_id: manifest.fleet_id,
        name: entry.name,

        // Only include vessel_id if defined
        ...(entry.vessel_id ? { vessel_id: entry.vessel_id } : {}),

        // Only include HA info if present
        ...(entry.ha ? { ha: entry.ha } : {})
    }
};

// === Fleet Table Bootstrap Updater ===
// Handles bootstrap/announce/{MAC} - enriches with manifest data
// ADDED: DNS resolve for driver devices → stores udp_ip::{vessel_id} in flow context


const parts = (msg.topic || '').split('/');
if (parts.length < 3) return null;

const mac = parts[2];
const p = msg.payload || {};
const status = p.status || 'pending';

// Load manifest and find device
const manifest = global.get('fleet_manifest');
let deviceInfo = null;

if (manifest && manifest.devices) {
    const norm = {};
    for (const [k, v] of Object.entries(manifest.devices)) {
        norm[k.toUpperCase()] = v;
    }
    deviceInfo = norm[mac.toUpperCase()];
}

// Update fleet table
let table = flow.get('fleet_table') || [];
let idx = table.findIndex(e => e.device_id === mac);

if (idx >= 0) {
    table[idx].status = status;
    table[idx].last_seen = new Date().toLocaleString();
    if (deviceInfo) {
        if (deviceInfo.name) table[idx].name = deviceInfo.name;
        if (deviceInfo.vessel_id) table[idx].vessel_id = deviceInfo.vessel_id;
        if (manifest.fleet_id) table[idx].fleet_id = manifest.fleet_id;
    }
} else {
    table.push({
        device_id: mac,
        name: deviceInfo?.name || '',
        fleet_id: manifest?.fleet_id || '',
        vessel_id: deviceInfo?.vessel_id || '',
        status: status,
        uptime: 0,
        last_seen: new Date().toLocaleString()
    });
}

flow.set('fleet_table', table);



return { payload: table };

// === Fleet Table Health/Status Updater ===
// Handles health messages from devices

const parts = (msg.topic || '').split('/');
const p = msg.payload || {};

// Parse topic: fleet/{fleet_id}/vessels/{vessel_id}/devices/{MAC}/health
if (parts.length < 6 || parts[0] !== 'fleet' || parts[2] !== 'vessels' || parts[4] !== 'devices' || parts[6] !== 'health') {
    return null; // Wrong topic format
}

const fleet_id = parts[1];
const vessel_id = parts[3];
const mac = parts[5];

// Validate MAC format (12 hex characters)
if (!mac || !/^[0-9A-F]{12}$/i.test(mac)) {
    node.warn(`Invalid MAC address: ${mac}`);
    return null;
}

let table = flow.get('fleet_table') || [];
let idx = table.findIndex(e => e.device_id === mac);

if (idx >= 0) {
    // Update health metrics for existing device only
    if (p.uptime !== undefined) table[idx].uptime = p.uptime;
    table[idx].last_seen = new Date().toLocaleString();
} else {
    // Don't create new entries from health messages - wait for bootstrap
    node.warn(`Health message from unknown device ${mac} - ignoring until bootstrapped`);
    return null;
}

flow.set('fleet_table', table);
return { payload: table };

// --- Bridge Filter ---
// Pass only CRSF messages from manifest devices with role "bridge".
// Adds fleet + source metadata for downstream routing.

const parts = (msg.topic || "").split("/");
if (parts.length < 5) return null;

const fleet_id = parts[1];
const device_id = (parts[3] || "").toUpperCase();

const manifest = global.get("fleet_manifest");
if (!manifest || !manifest.devices) return null;

// Build uppercase map once per message for case-insensitive lookup
const norm = {};
for (const [k, v] of Object.entries(manifest.devices)) {
  norm[k.toUpperCase()] = v;
}

const entry = norm[device_id];
if (!entry) return null; // IMPORTANT: avoid undefined.role crash

const roles = Array.isArray(entry.role) ? entry.role : [entry.role];
const roleNorm = roles.map(r => String(r || "").trim().toLowerCase());
if (!roleNorm.includes("bridge")) return null;

msg.meta = {
  fleet_id,
  source_device_id: device_id,
  source_name: entry.name || device_id
};

return msg;

// === Fleet Router ===
// CH10 <= 0 => ROV, CH10 > 0 => Tender
// output[0] = ROV path, output[1] = Tender path

const ch = msg.payload || {};
const manifest = global.get("fleet_manifest") || {};
const fleet_id = msg.meta?.fleet_id || manifest.fleet_id || "";

function normalizeRoles(role) {
  if (Array.isArray(role)) return role.map(r => String(r).trim().toLowerCase());
  if (typeof role === "string") return role.split(",").map(r => r.trim().toLowerCase()).filter(Boolean);
  return [];
}

function inferKind(vesselId) {
  const v = String(vesselId || "").toLowerCase();
  if (v.includes("tender")) return "tender";
  if (v.includes("rov")) return "rov";
  return null;
}

// Build unique list of driver vessels
const devices = Object.values(manifest.devices || {});
const driverVessels = [];
for (const dev of devices) {
  const roles = normalizeRoles(dev.role);
  if (!roles.includes("driver")) continue;
  if (!dev.vessel_id) continue;
  if (!driverVessels.includes(dev.vessel_id)) driverVessels.push(dev.vessel_id);
}
if (!driverVessels.length) {
  node.warn("No driver vessels found in manifest");
  return null;
}

const targetKind = Number(ch.ch10 || 0) > 0 ? "tender" : "rov";

// Resolve selected vessel
let vessel_id = manifest.defaults?.[targetKind] || null;
if (!vessel_id || !driverVessels.includes(vessel_id)) {
  vessel_id = driverVessels.find(v => inferKind(v) === targetKind) || null;
}
if (!vessel_id) vessel_id = driverVessels[0]; // IMPORTANT: fallback before latch writes

// Latch previous vessel on switch-away
const prevActive = flow.get("active_vessel_id");
if (prevActive && prevActive !== vessel_id) {
  const prevSnap = flow.get(`veh_last::${prevActive}`);
  if (prevSnap && Array.isArray(prevSnap.thr)) {
    flow.set(`veh_latched::${prevActive}`, true);
  }
}

// Active vessel is always live-controlled
flow.set(`veh_latched::${vessel_id}`, false);
flow.set("active_vessel_id", vessel_id);

// Extract role list for selected vessel
let roles = [];
for (const dev of devices) {
  if (dev.vessel_id === vessel_id) {
    roles = normalizeRoles(dev.role);
    break;
  }
}

msg.payload = Object.assign({}, ch, {
  heading: flow.get(`nav::${vessel_id}::heading`) || 0,
  pitch: flow.get(`nav::${vessel_id}::pitch`) || 0,
  roll: flow.get(`nav::${vessel_id}::roll`) || 0,
  lat: flow.get(`nav::${vessel_id}::lat`) || 0,
  lon: flow.get(`nav::${vessel_id}::lon`) || 0,
  depth: flow.get(`nav::${vessel_id}::depth`) || 0,
  pitch_rate: flow.get(`nav::${vessel_id}::pitch_rate`) || 0,
  roll_rate: flow.get(`nav::${vessel_id}::roll_rate`) || 0,
  yaw_rate: flow.get(`nav::${vessel_id}::yaw_rate`) || 0
});

msg.router = { fleet_id, vessel_id, kind: targetKind, roles };

// Heartbeat source cache
flow.set("last_channels", msg.payload);
flow.set("last_router", msg.router);

return targetKind === "rov" ? [msg, null] : [null, msg];

// ═══════════════════════════════════════════════════════════════════════════
// ROV FLIGHT MODE CONTROLLER - MANUAL / STABLE / MAG (GPS POSITION HOLD)
// ═══════════════════════════════════════════════════════════════════════════
//
// FLIGHT MODES:
// -------------
// MANUAL: Direct stick control, no stabilization
//   - Raw body-frame stick passthrough, no corrections
//   - Full pilot authority on all axes
//
// STABLE: Attitude/heading/depth hold with world-frame stick input
//   - Holds roll, pitch, yaw (heading), and depth at target setpoints
//   - Stick inputs transformed from world-frame to body-frame so that
//     "forward" is always forward relative to the water surface regardless
//     of current roll/pitch angle
//   - Pilot trims targets by moving sticks (setpoints follow stick input)
//   - PID control: P + I + D with gyro rate damping
//
// MAG: GPS position hold + attitude/depth hold
//   - Same world-frame stick transform as STABLE
//   - Additionally holds GPS lat/lon position
//   - Forces level flight (roll=0, pitch=0) for stable GPS tracking
//   - GPS errors converted to body-frame tilt commands
//   - Future: waypoint following / autonomous nav
//
// WORLD-TO-BODY STICK TRANSFORM (STABLE + MAG):
// -----------------------------------------------
// Pilot stick intent is in world-frame (relative to water surface).
// The transform rotates surge/sway/heave through current roll and pitch
// so the ROV moves as the pilot expects regardless of its attitude.
//
//   body_surge = heave_w·sin(p)           + surge_w·cos(p)
//   body_sway  = heave_w·sin(r)·cos(p)   + sway_w·cos(r)
//   body_heave = heave_w·cos(p)·cos(r)   - sway_w·sin(r) - surge_w·sin(p)
//
// Rotational axes (roll/pitch/yaw corrections from PID) are already in
// body-frame and are NOT transformed.
//
// CONTROL THEORY:
// ---------------
// PID: Output = P×error + I×∫error·dt + D×dError/dt
//   P: immediate response, can oscillate without damping
//   I: eliminates steady-state error (buoyancy, current, drift)
//   D: damping via gyro rates, prevents overshoot
//
// TUNING GUIDE:
// -------------
// 1. DEPTH HOLD:    P=0.3, I=0.05 (increase P until hold, I for offset)
// 2. HEADING HOLD:  P=0.2, I=0.02, D=0.06
// 3. ROLL STAB:     P=0.5, D=0.2  (no I-term)
// 4. PITCH STAB:    P=0.5, D=0.2  (no I-term)
// 5. GPS HOLD:      P=0.15, deadzone=1.0m, max_tilt=0.3
//
// SYMPTOMS AND FIXES:
// -------------------
// • Oscillation       → reduce P or increase D
// • Slow response     → increase P
// • Steady offset     → increase I
// • Jerky corrections → increase slew limits or filter alpha
// • GPS hunting       → increase gps_deadzone or reduce gps_P
// • Depth yo-yos      → check buoyancy first, then reduce depth_P
//
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════
// TUNABLE PARAMETERS
// ═══════════════════════════════════════════════════════════

const PARAMS = {
  deadband: 5,

  heading_trim_rate: 0.5,
  roll_trim_rate: 0.3,
  pitch_trim_rate: 0.3,
  depth_trim_rate: 0.05,

  heading_P: 0.2,
  roll_P: 0.3,
  pitch_P: 0.3,
  depth_P: 0.3,

  depth_I: 0.05,
  heading_I: 0.02,

  roll_D: 0.2,
  pitch_D: 0.2,
  yaw_D: 0.06,

  depth_I_max: 0.3,
  heading_I_max: 0.2,

  correction_exponent: 1.3,

  gps_P: 0.15,
  gps_max_tilt: 0.3,
  gps_deadzone: 1.0,
  gps_jump_threshold: 10,
  gps_slew_rate: 0.05,

  meters_per_deg_lat: 111000,
  meters_per_deg_lon: 88000,

  roll_slew: 0.1,
  pitch_slew: 0.1,
  yaw_slew: 0.1,
  heave_slew: 0.1,

  gyro_filter_alpha: 0.3,
  max_sensor_age: 2000,
};

// ═══════════════════════════════════════════════════════════
// UTILITY FUNCTIONS
// ═══════════════════════════════════════════════════════════

function clamp(v, min = -1, max = 1) {
  return Math.max(min, Math.min(max, v));
}

function applyDeadband(value, deadband) {
  return Math.abs(value) < deadband ? 0 : value;
}

function nonlinearCorrection(error, baseGain, exponent = PARAMS.correction_exponent) {
  const sign = Math.sign(error);
  const magnitude = Math.abs(error);
  return sign * baseGain * Math.pow(magnitude, exponent);
}

function slewLimit(current, target, maxDelta) {
  const delta = target - current;
  if (Math.abs(delta) <= maxDelta) return target;
  return current + Math.sign(delta) * maxDelta;
}

// Rotate world-frame stick inputs into body-frame using current roll/pitch.
// Inputs are in percent [-100, 100], output is also in percent [-100, 100].
// roll_deg and pitch_deg come from the IMU (ch.roll, ch.pitch).
function worldToBody(surge_w, sway_w, heave_w, roll_deg, pitch_deg) {
  const r = roll_deg * Math.PI / 180;
  const p = pitch_deg * Math.PI / 180;
  return {
    surge: heave_w * Math.sin(p) + surge_w * Math.cos(p),
    sway: heave_w * Math.sin(r) * Math.cos(p) + sway_w * Math.cos(r),
    heave: heave_w * Math.cos(p) * Math.cos(r) - sway_w * Math.sin(r) - surge_w * Math.sin(p)
  };
}

// ═══════════════════════════════════════════════════════════
// EXTRACT INPUT DATA
// ═══════════════════════════════════════════════════════════

const ch = msg.payload || {};
const vessel_id = msg.router?.vessel_id || 'rov-unknown';

// ═══════════════════════════════════════════════════════════
// PERSISTENT STATE - CONTEXT KEYS
// ═══════════════════════════════════════════════════════════

const keyLast = `rov:lastMode:${vessel_id}`;
const keyHead = `rov:targetHeading:${vessel_id}`;
const keyRoll = `rov:targetRoll:${vessel_id}`;
const keyPitch = `rov:targetPitch:${vessel_id}`;
const keyLat = `rov:targetLat:${vessel_id}`;
const keyLon = `rov:targetLon:${vessel_id}`;
const keyDepth = `rov:targetDepth:${vessel_id}`;

const keyDepthI = `rov:depthIntegral:${vessel_id}`;
const keyHeadingI = `rov:headingIntegral:${vessel_id}`;

const keyPrevRoll = `rov:prevRollCorr:${vessel_id}`;
const keyPrevPitch = `rov:prevPitchCorr:${vessel_id}`;
const keyPrevYaw = `rov:prevYawCorr:${vessel_id}`;
const keyPrevHeave = `rov:prevHeaveCorr:${vessel_id}`;
const keyPrevGPSRoll = `rov:prevGPSRollCorr:${vessel_id}`;
const keyPrevGPSPitch = `rov:prevGPSPitchCorr:${vessel_id}`;

const keyPrevNorth = `rov:prevNorthErr:${vessel_id}`;
const keyPrevEast = `rov:prevEastErr:${vessel_id}`;

const keyFilteredRollRate = `rov:filteredRollRate:${vessel_id}`;
const keyFilteredPitchRate = `rov:filteredPitchRate:${vessel_id}`;
const keyFilteredYawRate = `rov:filteredYawRate:${vessel_id}`;

const keyLastGyroTime = `rov:lastGyroTime:${vessel_id}`;
const keyLastDepthTime = `rov:lastDepthTime:${vessel_id}`;
const keyLastGPSTime = `rov:lastGPSTime:${vessel_id}`;

// ═══════════════════════════════════════════════════════════
// RESTORE PERSISTENT STATE
// ═══════════════════════════════════════════════════════════

let lastMode = context.get(keyLast);
let targetHeading = context.get(keyHead);
let targetRoll = context.get(keyRoll);
let targetPitch = context.get(keyPitch);
let targetLat = context.get(keyLat);
let targetLon = context.get(keyLon);
let targetDepth = context.get(keyDepth);
let depthIntegral = context.get(keyDepthI) || 0;
let headingIntegral = context.get(keyHeadingI) || 0;

let prevRollCorr = context.get(keyPrevRoll) || 0;
let prevPitchCorr = context.get(keyPrevPitch) || 0;
let prevYawCorr = context.get(keyPrevYaw) || 0;
let prevHeaveCorr = context.get(keyPrevHeave) || 0;
let prevGPSRollCorr = context.get(keyPrevGPSRoll) || 0;
let prevGPSPitchCorr = context.get(keyPrevGPSPitch) || 0;

let filteredRollRate = context.get(keyFilteredRollRate) || 0;
let filteredPitchRate = context.get(keyFilteredPitchRate) || 0;
let filteredYawRate = context.get(keyFilteredYawRate) || 0;

// ═══════════════════════════════════════════════════════════
// SENSOR STALENESS CHECK
// ═══════════════════════════════════════════════════════════

const nowMs = Date.now();

let lastGyroTime = context.get(keyLastGyroTime);
let lastDepthTime = context.get(keyLastDepthTime);
let lastGPSTime = context.get(keyLastGPSTime);

if (typeof ch.roll_rate === 'number' && typeof ch.pitch_rate === 'number' && typeof ch.yaw_rate === 'number') {
  lastGyroTime = nowMs;
  context.set(keyLastGyroTime, nowMs);
}

if (typeof ch.depth === 'number') {
  lastDepthTime = nowMs;
  context.set(keyLastDepthTime, nowMs);
}

if (typeof ch.lat === 'number' && typeof ch.lon === 'number') {
  lastGPSTime = nowMs;
  context.set(keyLastGPSTime, nowMs);
}

const gyroStale = (typeof lastGyroTime !== 'number') || (nowMs - lastGyroTime > PARAMS.max_sensor_age);
const depthStale = (typeof lastDepthTime !== 'number') || (nowMs - lastDepthTime > PARAMS.max_sensor_age);
const gpsStale = (typeof lastGPSTime !== 'number') || (nowMs - lastGPSTime > PARAMS.max_sensor_age);

// ═══════════════════════════════════════════════════════════
// MODE DETECTION AND TRANSITIONS
// ═══════════════════════════════════════════════════════════

const mode = ch.flight_mode || 'MANUAL';

function resetAllTargets() {
  targetHeading = null; targetRoll = null; targetPitch = null;
  targetLat = null; targetLon = null; targetDepth = null;
  depthIntegral = 0; headingIntegral = 0;
  prevRollCorr = 0; prevPitchCorr = 0; prevYawCorr = 0; prevHeaveCorr = 0;
  prevGPSRollCorr = 0; prevGPSPitchCorr = 0;
  context.set(keyHead, null); context.set(keyRoll, null);
  context.set(keyPitch, null); context.set(keyLat, null);
  context.set(keyLon, null); context.set(keyDepth, null);
  context.set(keyDepthI, 0); context.set(keyHeadingI, 0);
  context.set(keyPrevRoll, 0); context.set(keyPrevPitch, 0);
  context.set(keyPrevYaw, 0); context.set(keyPrevHeave, 0);
  context.set(keyPrevGPSRoll, 0); context.set(keyPrevGPSPitch, 0);
  context.set(keyPrevNorth, null); context.set(keyPrevEast, null);
}

if (mode === 'STABLE' && lastMode !== 'STABLE') {
  targetHeading = (typeof ch.heading === 'number') ? ch.heading : targetHeading;
  targetRoll = (typeof ch.roll === 'number') ? ch.roll : targetRoll;
  targetPitch = (typeof ch.pitch === 'number') ? ch.pitch : targetPitch;
  targetDepth = (typeof ch.depth === 'number') ? ch.depth : 1.0;
  depthIntegral = 0; headingIntegral = 0;
  prevRollCorr = 0; prevPitchCorr = 0; prevYawCorr = 0; prevHeaveCorr = 0;
  context.set(keyHead, targetHeading); context.set(keyRoll, targetRoll);
  context.set(keyPitch, targetPitch); context.set(keyDepth, targetDepth);
  context.set(keyDepthI, 0); context.set(keyHeadingI, 0);
  context.set(keyPrevRoll, 0); context.set(keyPrevPitch, 0);
  context.set(keyPrevYaw, 0); context.set(keyPrevHeave, 0);
}

if (mode === 'MAG' && lastMode !== 'MAG') {
  targetLat = (typeof ch.lat === 'number') ? ch.lat : targetLat;
  targetLon = (typeof ch.lon === 'number') ? ch.lon : targetLon;
  targetHeading = (typeof ch.heading === 'number') ? ch.heading : targetHeading;
  targetRoll = 0; targetPitch = 0;
  targetDepth = (typeof ch.depth === 'number') ? ch.depth : 1.0;
  depthIntegral = 0; headingIntegral = 0;
  prevRollCorr = 0; prevPitchCorr = 0; prevYawCorr = 0; prevHeaveCorr = 0;
  prevGPSRollCorr = 0; prevGPSPitchCorr = 0;
  context.set(keyLat, targetLat); context.set(keyLon, targetLon);
  context.set(keyHead, targetHeading); context.set(keyRoll, targetRoll);
  context.set(keyPitch, targetPitch); context.set(keyDepth, targetDepth);
  context.set(keyDepthI, 0); context.set(keyHeadingI, 0);
  context.set(keyPrevRoll, 0); context.set(keyPrevPitch, 0);
  context.set(keyPrevYaw, 0); context.set(keyPrevHeave, 0);
  context.set(keyPrevGPSRoll, 0); context.set(keyPrevGPSPitch, 0);
  context.set(keyPrevNorth, null); context.set(keyPrevEast, null);
}

if (mode === 'MANUAL') resetAllTargets();

context.set(keyLast, mode);

// ═══════════════════════════════════════════════════════════
// FILTER GYRO RATES (for D-term)
// ═══════════════════════════════════════════════════════════

if (!gyroStale) {
  const alpha = PARAMS.gyro_filter_alpha;
  filteredRollRate = alpha * (ch.roll_rate || 0) + (1 - alpha) * filteredRollRate;
  filteredPitchRate = alpha * (ch.pitch_rate || 0) + (1 - alpha) * filteredPitchRate;
  filteredYawRate = alpha * (ch.yaw_rate || 0) + (1 - alpha) * filteredYawRate;
  context.set(keyFilteredRollRate, filteredRollRate);
  context.set(keyFilteredPitchRate, filteredPitchRate);
  context.set(keyFilteredYawRate, filteredYawRate);
}

// ═══════════════════════════════════════════════════════════
// FLIGHT CONTROL LOGIC
// ═══════════════════════════════════════════════════════════

let roll_thrust = 0, pitch_thrust = 0, yaw_thrust = 0, heave_thrust = 0;

// ───────────────────────────────────────────────────────────
// MANUAL MODE - raw body-frame passthrough, no transform
// ───────────────────────────────────────────────────────────

if (mode === 'MANUAL') {
  roll_thrust = (ch.ch6 || 0) / 100;
  pitch_thrust = (ch.ch7 || 0) / 100;
  yaw_thrust = (ch.ch4 || 0) / 100;
  heave_thrust = (ch.ch3 || 0) / 100;
}

// ───────────────────────────────────────────────────────────
// STABLE MODE
// ───────────────────────────────────────────────────────────

else if (mode === 'STABLE') {

  // Rotational sticks - body-frame, used for target trimming only
  const roll_stick = applyDeadband(ch.ch6 || 0, PARAMS.deadband);
  const pitch_stick = applyDeadband(ch.ch7 || 0, PARAMS.deadband);
  const yaw_stick = applyDeadband(ch.ch4 || 0, PARAMS.deadband);

  // Translational sticks - world-frame intent, rotate to body-frame
  const surge_w = applyDeadband(ch.ch2 || 0, PARAMS.deadband);
  const sway_w = applyDeadband(ch.ch1 || 0, PARAMS.deadband);
  const heave_w = applyDeadband(ch.ch3 || 0, PARAMS.deadband);
  const body = worldToBody(surge_w, sway_w, heave_w, ch.roll || 0, ch.pitch || 0);
  const heave_stick = body.heave;

  // Overwrite ch so downstream thruster mixer sees body-frame values
  ch.ch1 = body.sway;
  ch.ch2 = body.surge;
  ch.ch3 = body.heave;

  // Target trimming
  if (roll_stick !== 0 && typeof targetRoll === 'number') {
    targetRoll += (roll_stick / 100) * PARAMS.roll_trim_rate;
    targetRoll = clamp(targetRoll, -45, 45);
    context.set(keyRoll, targetRoll);
  }
  if (pitch_stick !== 0 && typeof targetPitch === 'number') {
    targetPitch += (pitch_stick / 100) * PARAMS.pitch_trim_rate;
    targetPitch = clamp(targetPitch, -45, 45);
    context.set(keyPitch, targetPitch);
  }
  if (yaw_stick !== 0 && typeof targetHeading === 'number') {
    targetHeading += (yaw_stick / 100) * PARAMS.heading_trim_rate;
    targetHeading = ((targetHeading % 360) + 360) % 360;
    context.set(keyHead, targetHeading);
    headingIntegral = 0; context.set(keyHeadingI, 0);
  }
  if (heave_stick !== 0 && typeof targetDepth === 'number') {
    targetDepth += (heave_stick / 100) * PARAMS.depth_trim_rate;
    targetDepth = clamp(targetDepth, 0.5, 100);
    context.set(keyDepth, targetDepth);
    depthIntegral = 0; context.set(keyDepthI, 0);
  }

  // Errors
  const roll_err = (targetRoll || 0) - (ch.roll || 0);
  const pitch_err = (targetPitch || 0) - (ch.pitch || 0);
  let heading_err = 0;
  if (typeof targetHeading === 'number' && typeof ch.heading === 'number') {
    heading_err = targetHeading - ch.heading;
    heading_err = (((heading_err + 180) % 360) + 360) % 360 - 180;
  }
  let depth_err = 0;
  if (typeof targetDepth === 'number' && typeof ch.depth === 'number') {
    depth_err = targetDepth - ch.depth;
  }

  // Integrals
  if (heave_stick === 0 && !depthStale) {
    depthIntegral += depth_err * PARAMS.depth_I;
    depthIntegral = clamp(depthIntegral, -PARAMS.depth_I_max, PARAMS.depth_I_max);
    context.set(keyDepthI, depthIntegral);
  } else if (depthStale) { depthIntegral = 0; context.set(keyDepthI, 0); }

  if (yaw_stick === 0 && !gyroStale) {
    headingIntegral += heading_err * PARAMS.heading_I;
    headingIntegral = clamp(headingIntegral, -PARAMS.heading_I_max, PARAMS.heading_I_max);
    context.set(keyHeadingI, headingIntegral);
  } else if (gyroStale) { headingIntegral = 0; context.set(keyHeadingI, 0); }

  // PID
  let rollCorr = slewLimit(prevRollCorr, nonlinearCorrection(roll_err, PARAMS.roll_P) + (gyroStale ? 0 : -filteredRollRate * PARAMS.roll_D), PARAMS.roll_slew);
  let pitchCorr = slewLimit(prevPitchCorr, nonlinearCorrection(pitch_err, PARAMS.pitch_P) + (gyroStale ? 0 : -filteredPitchRate * PARAMS.pitch_D), PARAMS.pitch_slew);
  let yawCorr = slewLimit(prevYawCorr, nonlinearCorrection(heading_err, PARAMS.heading_P) + headingIntegral + (gyroStale ? 0 : -filteredYawRate * PARAMS.yaw_D), PARAMS.yaw_slew);
  let heaveCorr = slewLimit(prevHeaveCorr, (depthStale ? 0 : nonlinearCorrection(depth_err, PARAMS.depth_P)) + depthIntegral, PARAMS.heave_slew);

  context.set(keyPrevRoll, rollCorr); context.set(keyPrevPitch, pitchCorr);
  context.set(keyPrevYaw, yawCorr); context.set(keyPrevHeave, heaveCorr);

  roll_thrust = clamp(rollCorr);
  pitch_thrust = clamp(pitchCorr);
  yaw_thrust = clamp(yawCorr);
  heave_thrust = clamp(heaveCorr);
}

// ───────────────────────────────────────────────────────────
// MAG MODE
// ───────────────────────────────────────────────────────────

else if (mode === 'MAG') {

  // Rotational sticks - body-frame
  const roll_stick = applyDeadband(ch.ch6 || 0, PARAMS.deadband);
  const pitch_stick = applyDeadband(ch.ch7 || 0, PARAMS.deadband);
  const yaw_stick = applyDeadband(ch.ch4 || 0, PARAMS.deadband);

  // Translational sticks - world-frame → body-frame
  const surge_w = applyDeadband(ch.ch2 || 0, PARAMS.deadband);
  const sway_w = applyDeadband(ch.ch1 || 0, PARAMS.deadband);
  const heave_w = applyDeadband(ch.ch3 || 0, PARAMS.deadband);
  const body = worldToBody(surge_w, sway_w, heave_w, ch.roll || 0, ch.pitch || 0);
  const heave_stick = body.heave;

  ch.ch1 = body.sway;
  ch.ch2 = body.surge;
  ch.ch3 = body.heave;

  // Target trimming (heading + depth only in MAG)
  if (yaw_stick !== 0 && typeof targetHeading === 'number') {
    targetHeading += (yaw_stick / 100) * PARAMS.heading_trim_rate;
    targetHeading = ((targetHeading % 360) + 360) % 360;
    context.set(keyHead, targetHeading);
    headingIntegral = 0; context.set(keyHeadingI, 0);
  }
  if (heave_stick !== 0 && typeof targetDepth === 'number') {
    targetDepth += (heave_stick / 100) * PARAMS.depth_trim_rate;
    targetDepth = clamp(targetDepth, 0.5, 100);
    context.set(keyDepth, targetDepth);
    depthIntegral = 0; context.set(keyDepthI, 0);
  }

  // Errors
  const roll_err = (targetRoll || 0) - (ch.roll || 0);
  const pitch_err = (targetPitch || 0) - (ch.pitch || 0);
  let heading_err = 0;
  if (typeof targetHeading === 'number' && typeof ch.heading === 'number') {
    heading_err = targetHeading - ch.heading;
    heading_err = (((heading_err + 180) % 360) + 360) % 360 - 180;
  }
  let depth_err = 0;
  if (typeof targetDepth === 'number' && typeof ch.depth === 'number') {
    depth_err = targetDepth - ch.depth;
  }

  // GPS position hold
  let gps_roll_corr = 0, gps_pitch_corr = 0;

  if (!gpsStale &&
    typeof targetLat === 'number' && typeof ch.lat === 'number' &&
    typeof targetLon === 'number' && typeof ch.lon === 'number' &&
    typeof ch.heading === 'number') {

    const north_err_m = (targetLat - ch.lat) * PARAMS.meters_per_deg_lat;
    const east_err_m = (targetLon - ch.lon) * PARAMS.meters_per_deg_lon;

    const prevNorthErr = context.get(keyPrevNorth);
    const prevEastErr = context.get(keyPrevEast);
    const havePrev = (typeof prevNorthErr === 'number') && (typeof prevEastErr === 'number');

    if (!havePrev) {
      context.set(keyPrevNorth, north_err_m);
      context.set(keyPrevEast, east_err_m);
    } else if (
      Math.abs(north_err_m - prevNorthErr) > PARAMS.gps_jump_threshold ||
      Math.abs(east_err_m - prevEastErr) > PARAMS.gps_jump_threshold
    ) {
      // GPS glitch - skip this cycle
    } else {
      context.set(keyPrevNorth, north_err_m);
      context.set(keyPrevEast, east_err_m);

      const headingRad = (ch.heading * Math.PI) / 180;
      const surge_err_m = north_err_m * Math.cos(headingRad) + east_err_m * Math.sin(headingRad);
      const sway_err_m = -north_err_m * Math.sin(headingRad) + east_err_m * Math.cos(headingRad);

      if (Math.abs(surge_err_m) > PARAMS.gps_deadzone) gps_pitch_corr = surge_err_m * PARAMS.gps_P;
      if (Math.abs(sway_err_m) > PARAMS.gps_deadzone) gps_roll_corr = sway_err_m * PARAMS.gps_P;

      gps_pitch_corr = clamp(slewLimit(prevGPSPitchCorr, clamp(gps_pitch_corr, -PARAMS.gps_max_tilt, PARAMS.gps_max_tilt), PARAMS.gps_slew_rate), -PARAMS.gps_max_tilt, PARAMS.gps_max_tilt);
      gps_roll_corr = clamp(slewLimit(prevGPSRollCorr, clamp(gps_roll_corr, -PARAMS.gps_max_tilt, PARAMS.gps_max_tilt), PARAMS.gps_slew_rate), -PARAMS.gps_max_tilt, PARAMS.gps_max_tilt);

      if (roll_stick !== 0) gps_roll_corr = 0;
      if (pitch_stick !== 0) gps_pitch_corr = 0;

      context.set(keyPrevGPSPitch, gps_pitch_corr);
      context.set(keyPrevGPSRoll, gps_roll_corr);
    }
  } else {
    context.set(keyPrevGPSPitch, 0);
    context.set(keyPrevGPSRoll, 0);
  }

  // Integrals
  if (heave_stick === 0 && !depthStale) {
    depthIntegral += depth_err * PARAMS.depth_I;
    depthIntegral = clamp(depthIntegral, -PARAMS.depth_I_max, PARAMS.depth_I_max);
    context.set(keyDepthI, depthIntegral);
  } else if (depthStale) { depthIntegral = 0; context.set(keyDepthI, 0); }

  if (yaw_stick === 0 && !gyroStale) {
    headingIntegral += heading_err * PARAMS.heading_I;
    headingIntegral = clamp(headingIntegral, -PARAMS.heading_I_max, PARAMS.heading_I_max);
    context.set(keyHeadingI, headingIntegral);
  } else if (gyroStale) { headingIntegral = 0; context.set(keyHeadingI, 0); }

  // PID
  let rollCorr = slewLimit(prevRollCorr, nonlinearCorrection(roll_err, PARAMS.roll_P) + (gyroStale ? 0 : -filteredRollRate * PARAMS.roll_D), PARAMS.roll_slew);
  let pitchCorr = slewLimit(prevPitchCorr, nonlinearCorrection(pitch_err, PARAMS.pitch_P) + (gyroStale ? 0 : -filteredPitchRate * PARAMS.pitch_D), PARAMS.pitch_slew);
  let yawCorr = slewLimit(prevYawCorr, nonlinearCorrection(heading_err, PARAMS.heading_P) + headingIntegral + (gyroStale ? 0 : -filteredYawRate * PARAMS.yaw_D), PARAMS.yaw_slew);
  let heaveCorr = slewLimit(prevHeaveCorr, (depthStale ? 0 : nonlinearCorrection(depth_err, PARAMS.depth_P)) + depthIntegral, PARAMS.heave_slew);

  context.set(keyPrevRoll, rollCorr); context.set(keyPrevPitch, pitchCorr);
  context.set(keyPrevYaw, yawCorr); context.set(keyPrevHeave, heaveCorr);

  roll_thrust = clamp(rollCorr + gps_roll_corr);
  pitch_thrust = clamp(pitchCorr + gps_pitch_corr);
  yaw_thrust = clamp(yawCorr);
  heave_thrust = clamp(heaveCorr);
}

// ═══════════════════════════════════════════════════════════
// OUTPUT
// ═══════════════════════════════════════════════════════════

msg.control = {
  roll_thrust,
  pitch_thrust,
  yaw_thrust,
  heave_thrust
};

return msg;

// ═══════════════════════════════════════════════════════════════════════════
// ROV 8-THRUSTER MIXER WITH PER-THRUSTER DEADBAND & REVERSE BIAS COMPENSATION
// ═══════════════════════════════════════════════════════════════════════════
//
// PURPOSE:
// --------
// Converts 6-axis control commands (surge/sway/heave/roll/pitch/yaw) into
// individual thruster power outputs for an 8-thruster ROV configuration.
// Applies per-thruster forward/reverse deadband compensation and reverse bias.
//
// INPUTS:
// -------
// From control loop (normalized [-1, 1]):
//   - control.roll_thrust   → roll correction
//   - control.pitch_thrust  → pitch correction
//   - control.yaw_thrust    → yaw correction
//   - control.heave_thrust  → heave/depth correction (or direct stick in MANUAL)
//
// From stick channels (percent [-100, 100]):
//   - ch1 → sway (left/right) — NOTE: inverted (-(ch1))
//   - ch2 → surge (forward/back)
//   - ch3 → heave (up/down) if not using control loop
//   - ch4 → yaw (used by control loop) — NOTE: inverted (-(yaw_thrust))
//   - ch5 → ARM switch: >0 = armed, <=0 = disarmed (zero packet sent)
//   - ch6 → roll (used by control loop)
//   - ch7 → pitch (used by control loop)
//
// OUTPUTS:
// --------
// output[0]: UDP binary packet → udp out node
//   - 18-byte packet: craft_type(1) + craft_id(1) + T1..T8 int16LE x10 (16)
//   - All thrusters zeroed if disarmed (CH5 <= 0)
//   - Zeros still sent when disarmed to keep ESP deadman timer alive
//   - msg.ip and msg.port set dynamically from flow context
//   - Dropped silently (with rate-limited warning) if udp_ip::{vessel_id}
//     not yet resolved
//
// output[1]: MQTT → kept for simulator / debug during UDP transition
//   - topic: fleet/{fleet_id}/vessels/{vessel_id}/thrusters/set
//   - payload: { thr: [t1..t8] } clamped to [-100, 100]
//
// THRUSTER LAYOUT:
// ----------------
//
// TOP VIEW (Horizontal thrusters 1-4: surge/sway/yaw)
// ----------------------------------------------------
//          Bow (forward)
//               ↑
//               |
//     [1] Port Bow    [2] Stbd Bow
//          ╱              ╲
//         ╱                ╲
//        ╱                  ╲
//       ╱                    ╲
//  [4] Port Stern      [3] Stbd Stern
//
// SIDE VIEW (Vertical thrusters 5-8: heave/roll/pitch)
// -----------------------------------------------------
//          Bow (forward)
//               ↑
//               |
//     [5] Port Bow (vert)    [6] Stbd Bow (vert)
//          ↕                      ↕
//
//     [8] Port Stern (vert)   [7] Stbd Stern (vert)
//          ↕                      ↕
//
// SIGN CONVENTIONS:
// -----------------
// Body frame (right-hand rule):
//   +Surge  = forward (bow direction)
//   +Sway   = starboard (right)  — ch1 is INVERTED
//   +Heave  = upward (toward surface)
//   +Roll   = roll right (starboard down, port up)
//   +Pitch  = nose down (bow down, stern up)
//   +Yaw    = turn right (clockwise from above) — yaw_thrust is INVERTED
//
// ═══════════════════════════════════════════════════════════════════════════

if (flow.get("safety_kill_active") === true) return null;


const ch = msg.payload || {};
const c = msg.control || {};
const fleet_id = msg.router?.fleet_id || '';
const vessel_id = msg.router?.vessel_id || 'rov-01';

// ═══════════════════════════════════════════════════════════
// ARM CHECK — CH5 > 0 = armed, <= 0 = disarmed
// When disarmed: zero packet is still sent to keep ESP deadman alive
// ═══════════════════════════════════════════════════════════

const armed = (ch.ch5 || 0) > 0;

// ═══════════════════════════════════════════════════════════
// TUNING PARAMETERS
// ═══════════════════════════════════════════════════════════

const ZERO_CUTOFF = 0.5;

const REVERSE_BIAS = {
  t1: 0.30, t2: 0.30, t3: 0.30, t4: 0.30,
  t5: 0.30, t6: 0.30, t7: 0.30, t8: 0.30
};

const REVERSE_GAIN = {
  t1: 1 + REVERSE_BIAS.t1, t2: 1 + REVERSE_BIAS.t2,
  t3: 1 + REVERSE_BIAS.t3, t4: 1 + REVERSE_BIAS.t4,
  t5: 1 + REVERSE_BIAS.t5, t6: 1 + REVERSE_BIAS.t6,
  t7: 1 + REVERSE_BIAS.t7, t8: 1 + REVERSE_BIAS.t8
};

const DEADBAND = {
  t1: { forward: 6, reverse: 0 }, t2: { forward: 6, reverse: 0 },
  t3: { forward: 6, reverse: 0 }, t4: { forward: 6, reverse: 0 },
  t5: { forward: 6, reverse: 0 }, t6: { forward: 6, reverse: 0 },
  t7: { forward: 6, reverse: 0 }, t8: { forward: 6, reverse: 0 }
};

// ═══════════════════════════════════════════════════════════
// INPUT EXTRACTION
// ═══════════════════════════════════════════════════════════

function inputDeadband(val, db) {
  return Math.abs(val) < db ? 0 : val;
}

let sway = (ch.ch1 || 0);
let surge = ch.ch2 || 0;

let heave = (c.heave_thrust !== undefined)
  ? inputDeadband(c.heave_thrust, 0.05) * 100
  : (ch.ch3 || 0);

let roll = inputDeadband(c.roll_thrust ?? 0, 0.05) * 100;
let pitch = inputDeadband(c.pitch_thrust ?? 0, 0.05) * 100;
let yaw = inputDeadband(c.yaw_thrust ?? 0, 0.05) * 100;

// ═══════════════════════════════════════════════════════════
// MIXER EQUATIONS
// ═══════════════════════════════════════════════════════════

let thr1 = surge - sway - yaw;
let thr2 = -surge - sway - yaw;
let thr3 = -surge + sway - yaw;
let thr4 = surge + sway - yaw;

let thr5 = -heave - roll - pitch;
let thr6 = heave - roll + pitch;
let thr7 = -heave + roll + pitch;
let thr8 = heave + roll - pitch;

let thr = [thr1, thr2, thr3, thr4, thr5, thr6, thr7, thr8];

// ═══════════════════════════════════════════════════════════
// FIRST NORMALISATION
// ═══════════════════════════════════════════════════════════

const max_cmd = Math.max(...thr.map(Math.abs));
if (max_cmd > 100) {
  const scale = 100 / max_cmd;
  thr = thr.map(t => t * scale);
}

// ═══════════════════════════════════════════════════════════
// REVERSE BIAS COMPENSATION
// ═══════════════════════════════════════════════════════════

function reverse_compensate(val, gain) {
  return (val < 0) ? val * gain : val;
}

thr[0] = reverse_compensate(thr[0], REVERSE_GAIN.t1);
thr[1] = reverse_compensate(thr[1], REVERSE_GAIN.t2);
thr[2] = reverse_compensate(thr[2], REVERSE_GAIN.t3);
thr[3] = reverse_compensate(thr[3], REVERSE_GAIN.t4);
thr[4] = reverse_compensate(thr[4], REVERSE_GAIN.t5);
thr[5] = reverse_compensate(thr[5], REVERSE_GAIN.t6);
thr[6] = reverse_compensate(thr[6], REVERSE_GAIN.t7);
thr[7] = reverse_compensate(thr[7], REVERSE_GAIN.t8);

// ═══════════════════════════════════════════════════════════
// DEADBAND COMPENSATION
// ═══════════════════════════════════════════════════════════

function deadband_compensate(val, fwd_db, rev_db) {
  if (val > ZERO_CUTOFF) {
    return fwd_db + (val / 100) * (100 - fwd_db);
  } else if (val < -ZERO_CUTOFF) {
    return -(rev_db + (Math.abs(val) / 100) * (100 - rev_db));
  }
  return 0;
}

thr[0] = deadband_compensate(thr[0], DEADBAND.t1.forward, DEADBAND.t1.reverse);
thr[1] = deadband_compensate(thr[1], DEADBAND.t2.forward, DEADBAND.t2.reverse);
thr[2] = deadband_compensate(thr[2], DEADBAND.t3.forward, DEADBAND.t3.reverse);
thr[3] = deadband_compensate(thr[3], DEADBAND.t4.forward, DEADBAND.t4.reverse);
thr[4] = deadband_compensate(thr[4], DEADBAND.t5.forward, DEADBAND.t5.reverse);
thr[5] = deadband_compensate(thr[5], DEADBAND.t6.forward, DEADBAND.t6.reverse);
thr[6] = deadband_compensate(thr[6], DEADBAND.t7.forward, DEADBAND.t7.reverse);
thr[7] = deadband_compensate(thr[7], DEADBAND.t8.forward, DEADBAND.t8.reverse);

// ═══════════════════════════════════════════════════════════
// SECOND NORMALISATION
// ═══════════════════════════════════════════════════════════

const max_final = Math.max(...thr.map(Math.abs));
if (max_final > 100) {
  const scale_final = 100 / max_final;
  thr = thr.map(t => t * scale_final);
}

// ═══════════════════════════════════════════════════════════
// CLAMP + ARM GATE
// If disarmed, override all outputs to zero.
// Zero packet is still sent to keep ESP deadman timer alive.
// ═══════════════════════════════════════════════════════════

function clamp(v) {
  return Math.max(-100, Math.min(100, Math.round(v)));
}

const thrClamped = armed ? thr.map(clamp) : [0, 0, 0, 0, 0, 0, 0, 0];

// Cache latest output for cross-vessel latching/replay
flow.set(`veh_last::${vessel_id}`, {
  fleet_id,
  vessel_id,
  thr: thrClamped,
  craft_type: 1, // ROV
  craft_id: Number(
    flow.get(`udp_craft_id::${String(vessel_id).trim().toLowerCase()}`) ??
    flow.get(`udp_craft_id::${vessel_id}`) ??
    1
  ),
  ts: Date.now()
});



// ═══════════════════════════════════════════════════════════
// OUTPUT 1: MQTT (simulator / debug — remove once UDP proven)
// ═══════════════════════════════════════════════════════════

const mqttMsg = {
  topic: `fleet/${fleet_id}/vessels/${vessel_id}/thrusters/set`,
  payload: { thr: thrClamped, armed }
};

// ═══════════════════════════════════════════════════════════
// OUTPUT 0: UDP binary packet
// ═══════════════════════════════════════════════════════════

// UPDATED: robust vessel key lookup (raw + normalized)
const vesselKey = String(vessel_id || "").trim().toLowerCase();
const udp_ip = flow.get(`udp_ip::${vesselKey}`) || flow.get(`udp_ip::${vessel_id}`) || null;


const craft_id = flow.get(`udp_craft_id::${vessel_id}`) || 2;

// Optional per-vessel enable switch (default true)
const enabled = flow.get(`vessel_enabled::${vessel_id}`);
if (enabled === false) {
  // Output order is [MQTT, UDP]
  return [mqttMsg, null];
}


// UPDATED: silent drop when no UDP IP (no log noise)
if (!udp_ip) {
  // Still publish MQTT debug/sim command
  return [mqttMsg, null];
}


// Build 18-byte packet:
//   byte 0:     craft_type = 1 (ROV8)
//   byte 1:     craft_id
//   bytes 2-17: T1..T8 as int16 little-endian, scaled x10
//               (-100 → -1000, +100 → +1000)
//   All zeros when disarmed
const buf = Buffer.alloc(18);
buf.writeUInt8(1, 0);
buf.writeUInt8(craft_id, 1);

for (let i = 0; i < 8; i++) {
  const val = Math.max(-1000, Math.min(1000, Math.round(thrClamped[i] * 10)));
  buf.writeInt16LE(val, 2 + i * 2);
}

const udpMsg = {
  payload: buf,
  ip: udp_ip,
  port: 14560
};

// Output order is [MQTT, UDP]
return [mqttMsg, udpMsg];

// ═══════════════════════════════════════════════════════════
// Tender Flight Mode Mixer - MANUAL / STABLE / MAG (GPS)
// ═══════════════════════════════════════════════════════════
//
// OVERVIEW:
// ---------
// This logic takes in raw stick inputs (channels) and current
// navigation state (heading, GPS position) and outputs corrected
// control commands for the tender.
//
// Modes:
//   MANUAL → Direct stick passthrough, no corrections
//   STABLE → Heading hold always; DP/GPS hold only when GPS lock is valid
//   MAG    → TEMPORARILY ALIASED TO STABLE (same behaviour for now)
//
// State is remembered between cycles using Node-RED `context`.
// Each vessel has its own stored state, identified by vessel_id.
// ═══════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════
// Tuning constants
// ═══════════════════════════════════════════════════════════

// Heading controller gains (PD)
const HEADING_KP = 0.70;          // proportional response
const HEADING_KD = 0.08;          // derivative damping (keep modest at 10 Hz)
const YAW_CORR_MAX = 55;          // clamp output command

// Heading behaviour shaping
const YAW_SLEW_PER_CYCLE = 10.0;   // max yaw correction change per cycle
const HEADING_DEADBAND_DEG = 1; // no correction inside this error band
const HEADING_TAPER_DEG = 5.0;   // taper correction as error approaches zero
const YAW_MIN_CORR = 8.0;         // new: minimum authority once off-heading

// Pilot yaw trim (changes heading target while yaw stick held)
const YAW_TRIM_DEADBAND = 5;
const YAW_TRIM_RATE_MAX = 45;     // deg/sec at full stick

// GPS position hold gains
const POS_KP = 2.0;
const POS_MAX_CORRECTION = 50;
const POS_DEADZONE = 1.5;         // meters
const GPS_SLEW = 5;               // per-cycle limiter
const MIN_SPEED_THRESHOLD = 0.5;  // disable position hold if moving faster than this
const GPS_JUMP_THRESHOLD = 10;    // reject sudden GPS jumps (meters)

// Approx conversions for local ENU approximation
const METERS_PER_DEG_LAT = 111000;
const METERS_PER_DEG_LON = 88000;

// Pilot override deadbands
const FORWARD_DEADBAND = 5;
const STRAFE_DEADBAND  = 5;
const YAW_CORR_DEADBAND = YAW_TRIM_DEADBAND;

// Minimum sats for DP hold
const MIN_SATS_FOR_DP = 5;


// ═══════════════════════════════════════════════════════════
// Inputs
// ═══════════════════════════════════════════════════════════

const ch = msg.payload || {};
const vessel_id = msg.router?.vessel_id || "tender-01";


// ═══════════════════════════════════════════════════════════
// Context keys (per vessel)
// ═══════════════════════════════════════════════════════════

const keyLast        = `tender:lastMode:${vessel_id}`;
const keyHead        = `tender:targetHeading:${vessel_id}`;
const keyLat         = `tender:targetLat:${vessel_id}`;
const keyLon         = `tender:targetLon:${vessel_id}`;
const keyTime        = `tender:lastTimeMs:${vessel_id}`;
const keyLastErr     = `tender:lastHeadingErr:${vessel_id}`;
const keyPrevYawCorr = `tender:prevYawCorr:${vessel_id}`;
const keyPrevFwd     = `tender:prevForwardCorr:${vessel_id}`;
const keyPrevStrafe  = `tender:prevStrafeCorr:${vessel_id}`;
const keyPrevNorth   = `tender:prevNorthErr:${vessel_id}`;
const keyPrevEast    = `tender:prevEastErr:${vessel_id}`;


// ═══════════════════════════════════════════════════════════
// Restore state
// ═══════════════════════════════════════════════════════════

let lastMode        = context.get(keyLast);
let targetHeading   = context.get(keyHead);
let targetLat       = context.get(keyLat);
let targetLon       = context.get(keyLon);
let lastHeadingErr  = context.get(keyLastErr) || 0;
let prevYawCorr     = context.get(keyPrevYawCorr) || 0;
let prevForwardCorr = context.get(keyPrevFwd) || 0;
let prevStrafeCorr  = context.get(keyPrevStrafe) || 0;


// ═══════════════════════════════════════════════════════════
// Mode normalize (MAG -> STABLE for now)
// ═══════════════════════════════════════════════════════════

const modeIn = String(ch.flight_mode || "MANUAL").toUpperCase();
const mode = (modeIn === "MAG") ? "STABLE" : modeIn;


// ═══════════════════════════════════════════════════════════
// Delta time
// ═══════════════════════════════════════════════════════════

const nowMs = Date.now();
let lastTimeMs = context.get(keyTime);
let dt = 0;

if (typeof lastTimeMs === "number") {
  dt = (nowMs - lastTimeMs) / 1000;
  // Reject bad dt values from stalls or clock jumps
  if (dt <= 0 || dt > 1) dt = 0;
}
context.set(keyTime, nowMs);


// ═══════════════════════════════════════════════════════════
// GPS lock validity
// ═══════════════════════════════════════════════════════════

const hasLatLon =
  typeof ch.lat === "number" &&
  typeof ch.lon === "number" &&
  !(Math.abs(ch.lat) < 0.0001 && Math.abs(ch.lon) < 0.0001);

const satsOk = (typeof ch.sats !== "number") || (ch.sats >= MIN_SATS_FOR_DP);
const gpsLock = hasLatLon && satsOk;


// ═══════════════════════════════════════════════════════════
// Mode transitions
// ═══════════════════════════════════════════════════════════

if (mode === "STABLE" && lastMode !== "STABLE") {
  // Entering hold mode: capture heading target
  if (typeof ch.heading === "number") {
    targetHeading = ch.heading;
    context.set(keyHead, targetHeading);
  }

  // Capture position only if GPS lock valid
  if (gpsLock) {
    targetLat = ch.lat;
    targetLon = ch.lon;
    context.set(keyLat, targetLat);
    context.set(keyLon, targetLon);
  } else {
    targetLat = null;
    targetLon = null;
    context.set(keyLat, null);
    context.set(keyLon, null);
  }
}

if (mode === "MANUAL") {
  // Leaving hold: clear targets/corrections so nothing carries over
  targetHeading = null;
  targetLat = null;
  targetLon = null;
  lastHeadingErr = 0;
  prevYawCorr = 0;
  prevForwardCorr = 0;
  prevStrafeCorr = 0;

  context.set(keyHead, null);
  context.set(keyLat, null);
  context.set(keyLon, null);
  context.set(keyLastErr, 0);
  context.set(keyPrevYawCorr, 0);
  context.set(keyPrevFwd, 0);
  context.set(keyPrevStrafe, 0);
  context.set(keyPrevNorth, null);
  context.set(keyPrevEast, null);
}

context.set(keyLast, mode);


// ═══════════════════════════════════════════════════════════
// Inputs
// ═══════════════════════════════════════════════════════════

let forward = (typeof ch.ch2 === "number") ? ch.ch2 : 0; // surge
let strafe  = (typeof ch.ch1 === "number") ? ch.ch1 : 0; // sway
let yawIn   = (typeof ch.ch4 === "number") ? ch.ch4 : 0; // yaw stick

let yawCorr = 0;
let forwardCorr = 0;
let strafeCorr = 0;

// ═══════════════════════════════════════════════════════════
// Heading hold (STABLE)
// ═══════════════════════════════════════════════════════════
if (
  mode === "STABLE" &&
  typeof targetHeading === "number" &&
  typeof ch.heading === "number"
) {
  const currentHeading = ((ch.heading % 360) + 360) % 360;
  targetHeading = ((targetHeading % 360) + 360) % 360;

  // Pilot yaw trim moves target heading instead of fighting controller
  if (Math.abs(yawIn) > YAW_TRIM_DEADBAND && dt > 0) {
    const yawNorm = Math.max(-100, Math.min(100, yawIn));
    const rateDegPerSec = (yawNorm / 100) * YAW_TRIM_RATE_MAX;

    targetHeading = (targetHeading + rateDegPerSec * dt + 360) % 360;
    context.set(keyHead, targetHeading);

    yawCorr = 0;
    lastHeadingErr = 0;
    context.set(keyLastErr, 0);
  } else {
    // Wrapped heading error in [-180, +180]
    let err = targetHeading - currentHeading;
    err = (((err + 180) % 360) + 360) % 360 - 180;

    // Derivative on error (simple discrete form)
    let errRate = 0;
    if (dt >= 0.02 && dt <= 0.3) {
      errRate = (err - lastHeadingErr) / dt;
    }

    lastHeadingErr = err;
    context.set(keyLastErr, err);

    const absErr = Math.abs(err);

    // Deadband near setpoint avoids micro-oscillation
    if (absErr <= HEADING_DEADBAND_DEG) {
      yawCorr = 0;
    } else {
      yawCorr = HEADING_KP * err + HEADING_KD * errRate;

      // Taper near setpoint to reduce overshoot
      if (absErr < HEADING_TAPER_DEG) {
        yawCorr *= (absErr / HEADING_TAPER_DEG);
      }

      yawCorr = Math.max(-YAW_CORR_MAX, Math.min(YAW_CORR_MAX, yawCorr));

      // Minimum correction so nose doesn't drift forever
      if (Math.abs(yawCorr) < YAW_MIN_CORR) {
        yawCorr = Math.sign(err) * YAW_MIN_CORR;
      }
    }

    // If pilot is actively yawing, disable auto yaw correction
    if (Math.abs(yawIn) > YAW_CORR_DEADBAND) {
      yawCorr = 0;
    }
  }

  // Slew limit correction change to prevent abrupt flips
  const yawDelta = yawCorr - prevYawCorr;
  if (Math.abs(yawDelta) > YAW_SLEW_PER_CYCLE) {
    yawCorr = prevYawCorr + Math.sign(yawDelta) * YAW_SLEW_PER_CYCLE;
  }

  prevYawCorr = yawCorr;
  context.set(keyPrevYawCorr, prevYawCorr);
}


// ═══════════════════════════════════════════════════════════
// GPS position hold (STABLE only, when lock valid)
// ═══════════════════════════════════════════════════════════

if (
  mode === "STABLE" &&
  gpsLock &&
  typeof targetLat === "number" &&
  typeof targetLon === "number" &&
  typeof ch.heading === "number"
) {
  const isMoving = (typeof ch.speed === "number" && ch.speed > MIN_SPEED_THRESHOLD);

  if (!isMoving) {
    // Position error in local meters
    const lat_err_deg = targetLat - ch.lat;
    const lon_err_deg = targetLon - ch.lon;

    const north_err_m = lat_err_deg * METERS_PER_DEG_LAT;
    const east_err_m  = lon_err_deg * METERS_PER_DEG_LON;

    const prevNorthErr = context.get(keyPrevNorth);
    const prevEastErr = context.get(keyPrevEast);
    const havePrev = (typeof prevNorthErr === "number") && (typeof prevEastErr === "number");

    if (!havePrev) {
      // Prime history on first sample
      context.set(keyPrevNorth, north_err_m);
      context.set(keyPrevEast, east_err_m);
      forwardCorr = 0;
      strafeCorr = 0;
    } else {
      // Reject obvious GPS jumps
      const northDelta = Math.abs(north_err_m - prevNorthErr);
      const eastDelta  = Math.abs(east_err_m - prevEastErr);

      if (northDelta > GPS_JUMP_THRESHOLD || eastDelta > GPS_JUMP_THRESHOLD) {
        forwardCorr = 0;
        strafeCorr = 0;
      } else {
        context.set(keyPrevNorth, north_err_m);
        context.set(keyPrevEast, east_err_m);

        // Rotate N/E error into vessel forward/strafe frame
        const headingRad = (ch.heading * Math.PI) / 180;
        const forward_err_m = north_err_m * Math.cos(headingRad) + east_err_m * Math.sin(headingRad);
        const strafe_err_m  = -north_err_m * Math.sin(headingRad) + east_err_m * Math.cos(headingRad);

        if (Math.abs(forward_err_m) > POS_DEADZONE) forwardCorr = forward_err_m * POS_KP;
        if (Math.abs(strafe_err_m) > POS_DEADZONE)  strafeCorr  = strafe_err_m * POS_KP;

        forwardCorr = Math.max(-POS_MAX_CORRECTION, Math.min(POS_MAX_CORRECTION, forwardCorr));
        strafeCorr  = Math.max(-POS_MAX_CORRECTION, Math.min(POS_MAX_CORRECTION, strafeCorr));

        // Smooth GPS corrections
        forwardCorr = Math.max(prevForwardCorr - GPS_SLEW, Math.min(prevForwardCorr + GPS_SLEW, forwardCorr));
        strafeCorr  = Math.max(prevStrafeCorr  - GPS_SLEW, Math.min(prevStrafeCorr  + GPS_SLEW, strafeCorr));

        context.set(keyPrevFwd, forwardCorr);
        context.set(keyPrevStrafe, strafeCorr);
      }
    }
  } else {
    // If vessel is already moving, avoid fighting pilot dynamics
    forwardCorr = 0;
    strafeCorr = 0;
    context.set(keyPrevFwd, 0);
    context.set(keyPrevStrafe, 0);
  }
} else {
  // No valid GPS hold conditions: clear DP correction state
  forwardCorr = 0;
  strafeCorr = 0;
  context.set(keyPrevFwd, 0);
  context.set(keyPrevStrafe, 0);
  context.set(keyPrevNorth, null);
  context.set(keyPrevEast, null);
}


// ═══════════════════════════════════════════════════════════
// Pilot override gates
// ═══════════════════════════════════════════════════════════

if (Math.abs(forward) > FORWARD_DEADBAND) forwardCorr = 0;
if (Math.abs(strafe) > STRAFE_DEADBAND) strafeCorr = 0;


// ═══════════════════════════════════════════════════════════
// Output control command
// ═══════════════════════════════════════════════════════════

msg.control = {
  forward: forward + forwardCorr,
  strafe:  strafe + strafeCorr,
  yaw:     yawIn + yawCorr
};

msg.control = {
  forward: forward + forwardCorr,
  strafe: strafe + strafeCorr,
  yaw: yawIn + yawCorr,
  target_heading: (typeof targetHeading === "number") ? targetHeading : null,
  heading_error: (typeof lastHeadingErr === "number") ? lastHeadingErr : null
};

// Optional: store for UI nodes
flow.set(`target_heading::${vessel_id}`, msg.control.target_heading);



return msg;


